SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Abide — Християнство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'abide.co' OR LOWER(`name`) = LOWER('Abide'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Abide', NULL, 'https://abide.co', NULL, NULL, 'Abide — християнський застосунок для медитації, молитви й сну на основі Біблії: аудіомедитації, історії для сну й ресурси на теми тривоги, горя, стресу та добробуту.', 'Abide is a Christian app for Bible-based meditation, prayer and sleep: audio meditations, sleep stories and resources on anxiety, grief, stress and wellness.', 'Abide пропонує нові способи спілкування з Богом через християнську медитацію. У застосунку є біблійні медитації, молитви й історії для сну, а на сайті — статті й ресурси на теми тривоги, горя, молитви, сну, стресу та добробуту. Проєкт працює разом із Guideposts. Преміум-доступ можна спробувати 7 днів безкоштовно.', 'Abide offers new ways to connect with God through Christian meditation. The app includes Bible-based meditations, prayers and sleep stories, and the site has articles and resources on anxiety, grief, prayer, sleep, stress and wellness. The project works with Guideposts. Premium can be tried free for 7 days.', 'Біблійні медитації
Молитви й історії для сну
Ресурси про тривогу й стрес
7 днів безкоштовно', 'Bible-based meditations
Prayers and sleep stories
Resources on anxiety and stress
7-day free trial', 'Християни, які хочуть молитися й медитувати щодня.', 'Christians who want a daily prayer and meditation habit.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-07 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'abide.co' OR LOWER(`name`) = LOWER('Abide')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'religion' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'religion' AND s.`slug` = 'christianity' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'Abide is a Christian app for Bible-based meditation, prayer and sleep: audio meditations, sleep stories and resources on anxiety, grief, stress and wellness.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Abide offers new ways to connect with God through Christian meditation. The app includes Bible-based meditations, prayers and sleep stories, and the site has articles and resources on anxiety, grief, prayer, sleep, stress and wellness. The project works with Guideposts. Premium can be tried free for 7 days.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'Bible-based meditations
Prayers and sleep stories
Resources on anxiety and stress
7-day free trial', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Christians who want a daily prayer and meditation habit.', 'manual' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Пробний період', 'Free trial', 0.00, 'free', '7 днів Premium', '7 days of Premium' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Пробний період' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Free trial', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', '7 days of Premium', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Premium (щомісяця)', 'Premium Monthly', 9.99, 'month', 'Усі медитації й історії', 'All meditations and stories' FROM DUAL WHERE @new = 1;
SET @plan = IF(@new = 1, (SELECT `id` FROM `pricing_plans` WHERE `product_id` = @pid AND `plan_name` = 'Premium (щомісяця)' ORDER BY `id` DESC LIMIT 1), NULL);
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'plan_name', 'en', 'Premium Monthly', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
INSERT IGNORE INTO `pricing_plan_translations` (`plan_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @plan, 'description', 'en', 'All meditations and stories', 'manual' FROM DUAL WHERE @plan IS NOT NULL;
