SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pockettorah.com' OR LOWER(`name`) = LOWER('PocketTorah'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PocketTorah', NULL, 'https://www.pockettorah.com', NULL, NULL, 'PocketTorah — безкоштовний застосунок для вивчення співу щотижневої глави Тори й гафтари на будь-якому мобільному пристрої чи комп''ютері.', 'PocketTorah is a free app for learning to chant the weekly Torah and Haftarah portion on any mobile device or computer.', 'PocketTorah дає змогу вчити кантиляцію тижневої глави Тори й гафтари будь-де й будь-коли. Застосунок працює на мобільних пристроях і комп''ютерах, допомагає готуватися до читання в синагозі й до бар- чи бат-міцви. Проєкт створили Рассел Нейсс і Чарлі Шварц, він повністю безкоштовний.', 'PocketTorah lets you learn to chant the weekly Torah and Haftarah portion anywhere, any time. It runs on mobile devices and computers and helps prepare for reading in synagogue or for a bar or bat mitzvah. Created by Russel Neiss and Charlie Schwartz, it is completely free.', 'Кантиляція Тори
Гафтара
Підготовка до бар-міцви
Мобільні й ПК
Безкоштовно', 'Torah chanting
Haftarah
